import 'dart:convert';
import 'dart:ui';
import '../services/walkable_surface.dart';

/// Experimental interpretation of page 2 of GEM_Digital_Map_English.pdf.
/// Coordinates are SVG pixels, not camera-projected coordinates.
/// PDF-to-SVG: x=pdfTop*1.06610, y=(1080-pdfX)*1.06610-39.446.
/// Floor: curve 20, clipped to the SVG. The 65 obstacle candidates are
/// brown filled structural shapes with pixel area between 400 and 100000;
/// their polygons were simplified by at most one pixel. These are draft
/// drawing interpretations, NOT surveyed walls, doors or access clearances.
/// No nearest-point snapping or fabricated entrances are supplied here.
WalkableSurface buildMainBuildingDraftSurface() {
  final data=jsonDecode(_geometry) as Map<String,dynamic>;
  List<Offset> polygon(dynamic raw) => [
    for(final p in raw as List) Offset((p[0] as num).toDouble(),(p[1] as num).toDouble()),
  ];
  return WalkableSurface(floors:[polygon(data['floor'])],
    obstacles:[for(final p in data['obstacles'] as List)polygon(p)]);
}
